  const techLoad = useMemo(() => techs.map((tech) => ({ tech, jobs: activeJobs.filter((a) => a.technician_id === tech.id).length })).sort((a, b) => b.jobs - a.jobs), [techs, activeJobs]);
  const maxLoad = Math.max(1, ...techLoad.map((x) => x.jobs));
